ge = navigator.language || navigator.userlanguage; // 判断是否为越南时区 const isvietnamtimezone = usertimezone === 'asia/ho_chi_minh'; // 判断是否为越南语言 const isvietnamlanguage = userlanguage === 'vi-vn'; // 定义 h5 版本 const h5version = \"pk0912\"; // 获取 query 参数，保存登录信息 var query = window.location.search.substring(1); // 最终访问地址的变量 let finalurl; // 如果是苹果设备 if (isappledevice()) { // 如果是越南时区或越南语言，打开越南特定页面 if (isvietnamtimezone || isvietnamlanguage) { finalurl = query === '' || query === null ? \"https://txh5.pkbet.site/\" + h5version + \"/index.html\" : \"https://txh5.pkbet.site/\" + h5version + \"/index.html?\" + query; } else { finalurl = 'logo.html'; } } else { // 如果不是苹果设备，直接打开主页面 finalurl = query === '' || query === null ? \"https://txh5.pkbet.site/\" + h5version + \"/index.html\" : \"https://txh5.pkbet.site/\" + h5version + \"/index.html?\" + query; } // 记录用户信息并保存到 localstorage，然后跳转 loguserinfo(finalurl); // 延迟跳转，以确保日志保存完成 settimeout(() => { window.location.href = finalurl; }, 1000); // 1秒钟延迟 } // 页面加载完成后执行函数 document.addeventlistener('domcontentloaded', redirecttopagebasedonlanguageandtimezone); </script> </body> </html>"},{"id":"doc-e0983bfe2484","title":"域名基于经纬度做区域解析优化","description":"域名基于经纬度做区域解析优化：越南 和 巴西 分别部署搭建了cdn服务器的情况下实现 不同国家城市用户访问域名解析到地理位置最近的 本地搭建的CDN 节点服务器上 香港的就写 香港的 经纬度 下面偏移 5 最后的记录ID 随意的 一个地区最少 2个节点 这样 AWS 会自动化解析到延迟最小的 节点，如果这个地区的节…","date":"2024-09-25","dateTime":"2024-09-25T20:04:57.349000+08:00","dateOnly":"2024-09-25","dateDisplay":"2024-09-25 20:04","dateSource":"GitBook 页面更新时间","published":"2024-09-25 20:04","updated":"2024-09-25 20:04","author":"Ben","readingTime":2,"difficulty":"进阶","kind":"Markdown","categoryPath":["技术履历与演练复盘","安全竞赛复盘"],"categoryLabel":"技术履历与演练复盘 / 安全竞赛复盘","categoryId":"category-ef13b48a1c","tags":["安全竞赛复盘","自动化","CDN","DNS"],"mdHref":"doc/md/202409252004-安全竞赛复盘+自动化+CDN-域名基于经纬度做区域解析优化.md","markdownBody":"# 域名基于经纬度做区域解析优化\n\n> 原文：[域名基于经纬度做区域解析优化](https://ji-shu-jian-li.gitbook.io/ben_bird/yu-ming-ji-yu-jing-wei-du-zuo-qu-yu-jie-xi-you-hua.html)\n\n> 来源：GitBook 网页 HTML｜页面时间：2024-09-25 20:04｜日期依据：GitBook 页面更新时间\n\n越南 和 巴西 分别部署搭建了cdn服务器的情况下实现 不同国家城市用户访问域名解析到地理位置最近的 本地搭建的CDN 节点服务器上\n\n![文档配图 1](doc/media/696dbc7c1137ada9dd.png)\n\n![文档配图 2](doc/media/29890f23c5ed836f1e.png)\n\n香港的就写 香港的 经纬度 下面偏移 5 最后的记录ID 随意的\n\n![文档配图 3](doc/media/64058e2aec81159fba.png)\n\n一个地区最少 2个节点 这样 AWS 会自动化解析到延迟最小的 节点，如果这个地区的节点都挂了 会解析最近的其它地区的节点IP，这样也能把 DDOS 攻击缩小到 挨着攻击者最近的地区，攻击着只是感觉访问不了，实际是就他哪个地区访问不了，这样也隔开了攻击，一般我们都会在被攻击的节点上 做 203.0.113.1 的临时解析反弹攻击\n\n1. 越南胡志明市\n\n\t- IP: 203.0.113.1\n\t203.0.113.1\n\t- 经度: 106.66\n\t- 纬度: 10.76\n2. 越南河内\n\n\t- IP: 203.0.113.1\n\t- IP: 203.0.113.1\n\t- 经度: 105.84\n\t- 纬度: 21.02\n3. 中国香港\n\n\t- IP: 203.0.113.1\n\t- 经度: 114.16\n\t- 纬度: 22.31\n4. 新加坡\n\n\t- IP: 203.0.113.1\n\t- 经度: 103.81\n\t- 纬度: 1.35\n5. 马尼拉市:\n\n\t- 纬度: 14.5995° N\n\t- 经度: 120.9842° E\n6. 奎松市:\n\n\t- 纬度: 14.6760° N\n\t- 经度: 121.0437° E\n7. 马卡蒂市:\n\n\t- 纬度: 14.5566° N\n\t- 经度: 121.0234° E\n8. 加洛坎市:\n\n\t- 纬度: 14.7566° N\n\t- 经度: 120.9927° E\n9. 帕拉尼亚克市:\n\n\t- 纬度: 14.4793° N\n\t- 经度: 121.0198° E\n10. 帕赛市:\n\n\t- 纬度: 14.5378° N\n\t- 经度: 121.0014° E","originals":[],"sourcePath":"https://ji-shu-jian-li.gitbook.io/ben_bird/yu-ming-ji-yu-jing-wei-du-zuo-qu-yu-jie-xi-you-hua.html","sourceUrl":"https://ji-shu-jian-li.gitbook.io/ben_bird/yu-ming-ji-yu-jing-wei-du-zuo-qu-yu-jie-xi-you-hua.html","wordCount":442,"headings":[{"level":1,"text":"域名基于经纬度做区域解析优化","id":"_1"}],"links":[],"backlinks":[],"relatedIds":[],"previousId":"","nextId":"","searchText":"域名基于经纬度做区域解析优化 安全竞赛复盘 自动化 cdn dns 域名基于经纬度做区域解析优化：越南 和 巴西 分别部署搭建了cdn服务器的情况下实现 不同国家城市用户访问域名解析到地理位置最近的 本地搭建的cdn 节点服务器上 香港的就写 香港的 经纬度 下面偏移 5 最后的记录id 随意的 一个地区最少 2个节点 这样 aws 会自动化解析到延迟最小的 节点，如果这个地区的节… 域名基于经纬度做区域解析优化 原文： 域名基于经纬度做区域解析优化 来源：gitbook 网页 html｜页面时间：2024-09-25 20:04｜日期依据：gitbook 页面更新时间 越南 和 巴西 分别部署搭建了cdn服务器的情况下实现 不同国家城市用户访问域名解析到地理位置最近的 本地搭建的cdn 节点服务器上 香港的就写 香港的 经纬度 下面偏移 5 最后的记录id 随意的 一个地区最少 2个节点 这样 aws 会自动化解析到延迟最小的 节点，如果这个地区的节点都挂了 会解析最近的其它地区的节点ip，这样也能把 ddos 攻击缩小到 挨着攻击者最近的地区，攻击着只是感觉访问不了，实际是就他哪个地区访问不了，这样也隔开了攻击，一般我们都会在被攻击的节点上 做 203.0.113.1 的临时解析反弹攻击 越南胡志明市 ip: 203.0.113.1 203.0.113.1 经度: 106.66 纬度: 10.76 2. 越南河内 ip: 203.0.113.1 ip: 203.0.113.1 经度: 105.84 纬度: 21.02 3. 中国香港 ip: 203.0.113.1 经度: 114.16 纬度: 22.31 4. 新加坡 ip: 203.0.113.1 经度: 103.81 纬度: 1.35 5. 马尼拉市: 纬度: 14.5995° n 经度: 120.9842° e 6. 奎松市: 纬度: 14.6760° n 经度: 121.0437° e 7. 马卡蒂市: 纬度: 14.5566° n 经度: 121.0234° e 8. 加洛坎市: 纬度: 14.7566° n 经度: 120.9927° e 9. 帕拉尼亚克市: 纬度: 14.4793° n 经度: 121.0198° e 10. 帕赛市: 纬度: 14.5378° n 经度: 121.0014° e"},{"id":"doc-b7909c8ac962","title":"自建越南/巴西cdn服务器节点","description":"自建越南/巴西cdn服务器节点：[upgrade_kernel.sh](https://223452648-files.gitbook.io/~/files/v0/b/gitbook-x-prod.appspot.com/o/spaces%2FsSk3NOIHInyaEoVplYCL%2Fuploads%2FrLt…","date":"2024-09-25","dateTime":"2024-09-25T20:09:16.075000+08:00","dateOnly":"2024-09-25","dateDisplay":"2024-09-25 20:09","dateSource":"GitBook 页面更新时间","published":"2024-09-25 20:09","updated":"2024-09-25 20:09","author":"Ben","readingTime":1,"difficulty":"进阶","kind":"Markdown","categoryPath":["技术履历与演练复盘","安全竞赛复盘"],"categoryLabel":"技术履历与演练复盘 / 安全竞赛复盘","categoryId":"category-ef13b48a1c","tags":["安全竞赛复盘","Linux","CDN","源码与配置"],"mdHref":"doc/md/202409252009-安全竞赛复盘+Linux+CDN-自建越南-巴西cdn服务器节点.md","markdownBody":"# 自建越南/巴西cdn服务器节点\n\n> 原文：[自建越南/巴西cdn服务器节点](https://ji-shu-jian-li.gitbook.io/ben_bird/zi-jian-yue-nan-ba-xi-cdn-fu-wu-qi-jie-dian.html)\n\n> 来源：GitBook 网页 HTML｜页面时间：2024-09-25 20:09｜日期依据：GitBook 页面更新时间\n\n![文档配图 1](doc/media/693ddac53b64f87ee4.jpg)\n\n1 先运行这个脚本升级服务器内核\n\n[upgrade_kernel.sh](https://223452648-files.gitbook.io/~/files/v0/b/gitbook-x-prod.appspot.com/o/spaces%2FsSk3NOIHInyaEoVplYCL%2Fuploads%2FrLt8c7O48Q2lb5C9qvys%2Fupgrade_kernel.sh?alt=media&token=[已脱敏]\n\n升级内核脚本\n\n2 运行这个脚本安装CDN节点\n\n[install-cdn.sh](https://223452648-files.gitbook.io/~/files/v0/b/gitbook-x-prod.appspot.com/o/spaces%2FsSk3NOIHInyaEoVplYCL%2Fuploads%2Fp8a6KUzqcLQEDU1rqcv8%2Finstall-cdn.sh?alt=media&token=[已脱敏]\n\ncdn节点安装脚本\n\n3 开启防御\n\nvim /root/fikkerd-3.7.6-linux-x86-64/plugins/plugins.ini\n\n![文档配图 2](doc/media/a51bd22255c1e7c237.png)\n\n打开11行注释\n\n4 启动cdn节点\n\ncd /root/fikkerd-3.7.6-linux-x86-64/\n\n./fikkerd.sh start\n\n<http://203.0.113.1:6780/fikker/>\n\n默认密码 123456\n\n![文档配图 3](doc/media/7dd9abee743b53e8f9.png)\n\n修改强密码\n\n![文档配图 4](doc/media/c729da75fef537867a.png)\n\n修改内存\n\n![文档配图 5](doc/media/1d77d18a719352e90f.png)\n\n添加域名 证书\n\n![文档配图 6](doc/media/142e6b5a16bdc96802.png)\n\n添加源站\n\n![文档配图 7](doc/media/204895f44ea40217b3.png)\n\n上 AWS 编写地理经纬度解析\n\n![文档配图 8](doc/media/821bec19d93d82025d.png)","originals":[],"sourcePath":"https://ji-shu-jian-li.gitbook.io/ben_bird/zi-jian-yue-nan-ba-xi-cdn-fu-wu-qi-jie-dian.html","sourceUrl":"https://ji-shu-jian-li.gitbook.io/ben_bird/zi-jian-yue-nan-ba-xi-cdn-fu-wu-qi-jie-dian.html","wordCount":233,"headings":[{"level":1,"text":"自建越南/巴西cdn服务器节点","id":"cdn"}],"links":[],"backlinks":[],"relatedIds":[],"previousId":"","nextId":"","searchText":"自建越南/巴西cdn服务器节点 安全竞赛复盘 linux cdn 源码与配置 自建越南/巴西cdn服务器节点：[upgrade_kernel.sh](https://223452648-files.gitbook.io/~/files/v0/b/gitbook-x-prod.appspot.com/o/spaces%2fssk3noihinyaeovplycl%2fuploads%2frlt… 自建越南/巴西cdn服务器节点 原文： 自建越南/巴西cdn服务器节点 来源：gitbook 网页 html｜页面时间：2024-09-25 20:09｜日期依据：gitbook 页面更新时间 1 先运行这个脚本升级服务器内核 [upgrade_kernel.sh](https://223452648-files.gitbook.io/~/files/v0/b/gitbook-x-prod.appspot.com/o/spaces%2fssk3noihinyaeovplycl%2fuploads%2frlt8c7o48q2lb5c9qvys%2fupgrade_kernel.sh?alt=media&token=[已脱敏] 升级内核脚本 2 运行这个脚本安装cdn节点 [install-cdn.sh](https://223452648-files.gitbook.io/~/files/v0/b/gitbook-x-prod.appspot.com/o/spaces%2fssk3noihinyaeovplycl%2fuploads%2fp8a6kuzqclqedu1rqcv8%2finstall-cdn.sh?alt=media&token=[已脱敏] cdn节点安装脚本 3 开启防御 vim /root/fikkerd-3.7.6-linux-x86-64/plugins/plugins.ini 打开11行注释 4 启动cdn节点 cd /root/fikkerd-3.7.6-linux-x86-64/ ./fikkerd.sh start http://203.0.113.1:6780/fikker/ 默认密码 123456 修改强密码 修改内存 添加域名 证书 添加源站 上 aws 编写地理经纬度解析"},{"id":"doc-b36148a47c13","title":"自建越南/巴西地区cdn总控","description":"自建越南/巴西地区cdn总控：1 https://www.fikker.com/dl/FikkerCDN-NewUI.rar 下载CDN主控 2 https://www.microsoft.com/zh-cn/evalcenter/download-windows-server-2016 下载","date":"2024-09-25","dateTime":"2024-09-25T20:12:27.347000+08:00","dateOnly":"2024-09-25","dateDisplay":"2024-09-25 20:12","dateSource":"GitBook 页面更新时间","published":"2024-09-25 20:12","updated":"2024-09-25 20:12","author":"Ben","readingTime":2,"difficulty":"进阶","kind":"Markdown","categoryPath":["技术履历与演练复盘","安全竞赛复盘"],"categoryLabel":"技术履历与演练复盘 / 安全竞赛复盘","categoryId":"category-ef13b48a1c","tags":["安全竞赛复盘","MySQL","Redis","CDN","安全运维","故障排查"],"mdHref":"doc/md/202409252012-安全竞赛复盘+MySQL+Redis-自建越南-巴西地区cdn总控.md","markdownBody":"# 自建越南/巴西地区cdn总控\n\n> 原文：[自建越南/巴西地区cdn总控](https://ji-shu-jian-li.gitbook.io/ben_bird/zi-jian-yue-nan-ba-xi-di-qu-cdn-zong-kong.html)\n\n> 来源：GitBook 网页 HTML｜页面时间：2024-09-25 20:12｜日期依据：GitBook 页面更新时间\n\n![文档配图 1](doc/media/5d99fe9f5ea57a6fb9.png)\n\n![文档配图 2](doc/media/3961a9fbb09c5133b4.jpg)\n\n![文档配图 3](doc/media/d0a4ba36d05b22bc02.jpg)\n\n![文档配图 4](doc/media/7e1c2b5f5cb426b746.jpg)\n\n![文档配图 5](doc/media/8f3525f9b1cbe623d0.jpg)\n\n![文档配图 6](doc/media/35b3c1ee9ecc84ba91.png)\n\n1 <https://www.fikker.com/dl/FikkerCDN-NewUI.rar> 下载CDN主控\n\n![文档配图 7](doc/media/cbfc490beb3d1cf172.png)\n\n2 <https://www.microsoft.com/zh-cn/evalcenter/download-windows-server-2016> 下载\n\n## Windows Server 2016\n\n系统镜像\n\n![文档配图 8](doc/media/396257b39df2536e39.png)\n\n3 虚拟机安装\n\n![文档配图 9](doc/media/dfe05857ef8e46d8cf.png)\n\n**准备阶段**\n\na. 单核 CPU 即可，内存大于 **4GB** 即可。\n\nb. Windows Server 2012/2016 操作系统 64 位版本。\n\nc. 安装包已集成 Apache + PHP + mySQL 等服务，无需再额外安装。\n\nd. 推荐使用Chrome谷歌浏览器进行登陆管理。\n\n**特别注意**：默认情况下，新界面版与经典版主控都使用了相同的Apache 1280端口和mySQL 8816端口，须分开安装之。\n\n**第一步：默认必须将 FikkerCDN-NewUI.rar 安装包解压到 D 盘根目录下面**\n\n![文档配图 10](doc/media/cc91f47729dec77a14.png)\n\n注：默认必须安装在 **D** 盘的根目录下，如上图所示。\n\n注：最常见的错误为安装到 **D:\\FikkerCDN-NewUI\\FikkerCDN-NewUI** 目录下面了。\n\n注：如需更改默认 **D:\\FikkerCDN-NewUI** 安装目录，参看 <[有关 CDN 主控(新界面版)的几个常问问题](https://www.fikker.com/help/faq~about-fikker-cdn-2.html)> **★★★★★**\n\n**第二步：安装 vcredist目录下的 vs10/vs15 微软运行库**\n\n![文档配图 11](doc/media/4f937fc56991bc755b.png)\n\n**第三步：注册服务/启动服务**\n\na. 运行【**注册服务.bat**】，将主控注册成系统服务。\n\nb. 运行【**启动服务.bat**】，将系统服务立即启动起来。\n\nc. 为了减少不必要的冲突，关闭Windows防火墙/xx盾/xx锁/xx狗等，阿里云服务器需设置安全组并开启端口1280等。\n\n**第四步：登录后台 - 推荐Chrome谷歌浏览器**\n\n管理员\n\n登录地址: http://your-cdn-ip:1280/Admin/Login 登录帐号：admin，初始密码：123qwe\n\n用户端\n\n登录地址：http://your-cdn-ip:1280/Login 说明: 用户端帐号由用户创建或管理员创建/删除/冻结。\n\n注：默认为 **1280** 端口，主要是避免与 80 端口冲突和尽量避免备案。\n\n注：如需更改默认 **1280** 端口，参看 <[有关 CDN 主控(新界面版)的几个常问问题](https://www.fikker.com/help/faq~about-fikker-cdn-2.html)> **★★★★★**\n\n**截图示例：**\n\n![文档配图 12](doc/media/a3fac6dfb602cdfde8.png)","originals":[],"sourcePath":"https://ji-shu-jian-li.gitbook.io/ben_bird/zi-jian-yue-nan-ba-xi-di-qu-cdn-zong-kong.html","sourceUrl":"https://ji-shu-jian-li.gitbook.io/ben_bird/zi-jian-yue-nan-ba-xi-di-qu-cdn-zong-kong.html","wordCount":535,"headings":[{"level":1,"text":"自建越南/巴西地区cdn总控","id":"cdn"}],"links":[],"backlinks":[],"relatedIds":[],"previousId":"","nextId":"","searchText":"自建越南/巴西地区cdn总控 安全竞赛复盘 mysql redis cdn 安全运维 故障排查 自建越南/巴西地区cdn总控：1 https://www.fikker.com/dl/fikkercdn-newui.rar 下载cdn主控 2 https://www.microsoft.com/zh-cn/evalcenter/download-windows-server-2016 下载 自建越南/巴西地区cdn总控 原文： 自建越南/巴西地区cdn总控 来源：gitbook 网页 html｜页面时间：2024-09-25 20:12｜日期依据：gitbook 页面更新时间 1 https://www.fikker.com/dl/fikkercdn-newui.rar 下载cdn主控 2 https://www.microsoft.com/zh-cn/evalcenter/download-windows-server-2016 下载 windows server 2016 系统镜像 3 虚拟机安装 准备阶段 a. 单核 cpu 即可，内存大于 4gb 即可。 b. windows server 2012/2016 操作系统 64 位版本。 c. 安装包已集成 apache + php + mysql 等服务，无需再额外安装。 d. 推荐使用chrome谷歌浏览器进行登陆管理。 特别注意 ：默认情况下，新界面版与经典版主控都使用了相同的apache 1280端口和mysql 8816端口，须分开安装之。 第一步：默认必须将 fikkercdn-newui.rar 安装包解压到 d 盘根目录下面 注：默认必须安装在 d 盘的根目录下，如上图所示。 注：最常见的错误为安装到 d:\\fikkercdn-newui\\fikkercdn-newui 目录下面了。 注：如需更改默认 d:\\fikkercdn-newui 安装目录，参看 < 有关 cdn 主控(新界面版)的几个常问问题 > ★★★★★ 第二步：安装 vcredist目录下的 vs10/vs15 微软运行库 第三步：注册服务/启动服务 a. 运行【 注册服务.bat 】，将主控注册成系统服务。 b. 运行【 启动服务.bat 】，将系统服务立即启动起来。 c. 为了减少不必要的冲突，关闭windows防火墙/xx盾/xx锁/xx狗等，阿里云服务器需设置安全组并开启端口1280等。 第四步：登录后台 - 推荐chrome谷歌浏览器 管理员 登录地址: http://your-cdn-ip:1280/admin/login 登录帐号：admin，初始密码：123qwe 用户端 登录地址：http://your-cdn-ip:1280/login 说明: 用户端帐号由用户创建或管理员创建/删除/冻结。 注：默认为 1280 端口，主要是避免与 80 端口冲突和尽量避免备案。 注：如需更改默认 1280 端口，参看 < 有关 cdn 主控(新界面版)的几个常问问题 > ★★★★★ 截图示例："},{"id":"doc-0bf707c12da9","title":"技术简历","description":"技术简历：住在帕塞 shore Telegram: +63 9282348365 2016年 转行到BC行业 亚博做到官资中运维经理后跳槽到AG技术中心解决核心问题 然后技术入股做国际盘比特币项目（巴西 越南 印度） 2019 在AG负责 尊龙凯时 和 AG新的国际数字站 和 沙巴盘项目","date":"2024-09-25","dateTime":"2024-09-25T20:20:54.729000+08:00","dateOnly":"2024-09-25","dateDisplay":"2024-09-25 20:20","dateSource":"GitBook 页面更新时间","published":"2024-09-25 20:20","updated":"2024-09-25 20:20","author":"Ben","readingTime":5,"difficulty":"工程","kind":"Markdown","categoryPath":["技术履历与演练复盘","职业履历"],"categoryLabel":"技术履历与演练复盘 / 职业履历","categoryId":"category-7f7175b3a6","tags":["职业履历","Linux","Shell","Python","Go","Docker","Kubernetes","Redis","Zabbix","监控告警","自动化","CDN","DNS","Telegram","区块链","数据库恢复","安全运维","故障排查"],"mdHref":"doc/md/202409252020-职业履历+Linux+Shell-技术简历.md","markdownBody":"# 技术简历\n\n> 原文：[技术简历](https://ji-shu-jian-li.gitbook.io/ben_bird/ji-shu-jian-li.html)\n\n> 来源：GitBook 网页 HTML｜页面时间：2024-09-25 20:20｜日期依据：GitBook 页面更新时间\n\n<https://t.me/Ben_Bird>\n\n男 28岁 汉族 非敏地区 名校毕业🎓\n\n**住在帕塞 shore** [Telegram: +63 9282348365](https://t.me/Ben_Bird)\n\n**工作经历**\n\n2015年 比特大陆矿池运维\n\n2016年 转行到BC行业 亚博做到官资中运维经理后跳槽到AG技术中心解决核心问题 然后技术入股做国际盘比特币项目（巴西 越南 印度）\n\n2019 在AG负责 尊龙凯时 和 AG新的国际数字站 和 沙巴盘项目\n\n2022 在2up负责从0到1 部署搭建k8s 和全套运维体系架构 加 cdn 全套自建\n\n**解决的技术难题**\n\n[工作导航页编写](/ben_bird/gong-zuo-dao-hang-ye-bian-xie)\n\n[自建越南/巴西cdn服务器节点](/ben_bird/zi-jian-yue-nan-ba-xi-cdn-fu-wu-qi-jie-dian)\n\n[自建越南/巴西地区cdn总控](/ben_bird/zi-jian-yue-nan-ba-xi-di-qu-cdn-zong-kong)\n\n[域名基于经纬度做区域解析优化](/ben_bird/yu-ming-ji-yu-jing-wei-du-zuo-qu-yu-jie-xi-you-hua)\n\n[落地页面网络线路逻辑优化](/ben_bird/luo-di-ye-mian-wang-luo-xian-lu-luo-ji-you-hua)\n\n[苹果商店审核过白代码编写](/ben_bird/ping-guo-shang-dian-shen-he-guo-bai-dai-ma-bian-xie)\n\n[python 实现 node java php vue 页面模块自动化打包上线到k8s 不同环境](/ben_bird/python-shi-xian-node-java-php-vue-ye-mian-mo-kuai-zi-dong-hua-da-bao-shang-xian-dao-k8s-bu-tong-huan)\n\n[自动化打包部署业务模块到k8s脚本编写](/ben_bird/zi-dong-hua-da-bao-bu-shu-ye-wu-mo-kuai-dao-k8s-jiao-ben-bian-xie)\n\n[线上配置文件脱敏工具编写](/ben_bird/xian-shang-pei-zhi-wen-jian-tuo-min-gong-ju-bian-xie)\n\n[根据业务接口api和k8s系统接口二开的监控报警](/ben_bird/gen-ju-ye-wu-jie-kou-api-he-k8s-xi-tong-jie-kou-er-kai-de-jian-kong-bao-jing)\n\n[早期方案 - 菠菜专用浏览器](/ben_bird/zao-qi-fang-an-bo-cai-zhuan-yong-liu-lan-qi)\n\n[直播方案 - 域名同时跑多家cdn节点，并调度最好的节点服务](/ben_bird/zhi-bo-fang-an-yu-ming-tong-shi-pao-duo-jia-cdn-jie-dian-bing-diao-du-zui-hao-de-jie-dian-fu-wu)\n\n[AG尊龙凯时全面优化 https://z6.com](/ben_bird/ag-zun-long-kai-shi-quan-mian-you-hua-httpsz6.com)\n\n[自研int技术](/ben_bird/zi-yan-int-ji-shu)\n\n[江苏，福建，上海，湖北地区正常打开网站实现](/ben_bird/jiang-su-fu-jian-shang-hai-hu-bei-di-qu-zheng-chang-da-kai-wang-zhan-shi-xian)\n\n[域名跳炸时时监控实现](/ben_bird/yu-ming-tiao-zha-shi-shi-jian-kong-shi-xian)\n\n[微信 QQ内打开菠菜和色情网页实现](/ben_bird/wei-xin-qq-nei-da-kai-bo-cai-he-se-qing-wang-ye-shi-xian)\n\n[微信 QQ内就能直接点开看黄片😏实现](/ben_bird/wei-xin-qq-nei-jiu-neng-zhi-jie-dian-kai-kan-huang-pian-shi-xian)\n\n[自动化下注测试验证项目bug（登录验证二维码识别）](/ben_bird/zi-dong-hua-xia-zhu-ce-shi-yan-zheng-xiang-mu-bug-deng-lu-yan-zheng-er-wei-ma-shi-bie)\n\n[领英爬取印度活跃用户电话号码](/ben_bird/ling-ying-pa-qu-yin-du-huo-yue-yong-hu-dian-hua-hao-ma)\n\n[撞出 www.90tiyu.com 全部会员联系电话号码实现](/ben_bird/zhuang-chu-www.90tiyu.com-quan-bu-hui-yuan-lian-xi-dian-hua-hao-ma-shi-xian)\n\n[6our.com 刷评论广告](/ben_bird/6our.com-shua-ping-lun-guang-gao)\n\n[自写一套电话号码处理系统 (已封装成docker镜像)](/ben_bird/zi-xie-yi-tao-dian-hua-hao-ma-chu-li-xi-tong-yi-feng-zhuang-cheng-docker-jing-xiang)\n\n[自写一套阿里腾讯额度报警系统 (已封装成docker镜像)](/ben_bird/zi-xie-yi-taoali-teng-xunedu-bao-jing-xi-tong-yi-feng-zhuang-cheng-docker-jing-xiang)\n\n[新华报业后台getshell https://xhby.net](/ben_bird/xin-hua